begin;
select no_plan();
insert into auth.users(id,aud,role,email) values
 ('00000000-0000-4000-8000-000000000091','authenticated','authenticated','ops-owner@example.invalid'),
 ('00000000-0000-4000-8000-000000000092','authenticated','authenticated','ops-manager@example.invalid'),
 ('00000000-0000-4000-8000-000000000093','authenticated','authenticated','ops-outsider@example.invalid');
insert into public.ten29_admins(user_id,role) values('00000000-0000-4000-8000-000000000091','OWNER'),('00000000-0000-4000-8000-000000000092','MANAGER');
create temporary table f(request uuid,quote uuid,deposit uuid,reservation uuid,key uuid,payload jsonb);
grant all on f to authenticated;
insert into f(key,payload) values('00000000-0000-4000-8000-000000000094','{"source":"MESSENGER","package_code":"WHOLE_HOME_3BR","check_in_date":"2038-01-01","check_out_date":"2038-01-03","overnight_guest_count":2,"folding_foams_requested":false,"full_name":"Synthetic Private Guest","contact_number":"555-0100","email":"","notes":"Private"}');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000093',true);
select throws_ok($$select public.read_booking_operations('2038-01-01','2038-02-01',null)$$,'42501','TEN29 access required','nonmember cannot read operations');
select throws_ok($$select public.perform_booking_operation('MANUAL',null,key,payload) from f$$,'42501','TEN29 access required','nonmember cannot create manual request');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000092',true);
update f set request=public.perform_booking_operation('MANUAL',null,key,payload);
select is((select source::text from public.booking_requests where id=(select request from f)),'MESSENGER','manager manual source retained');
select is((select inquiry_id from public.booking_requests where id=(select request from f)),null::uuid,'manual request never fabricates enquiry');
select is((select overnight_guest_count::int from public.booking_requests where id=(select request from f)),2,'larger package supports two guests');
select is((select public.perform_booking_operation('MANUAL',null,key,payload) from f),(select request from f),'same-key retry returns original');
select throws_ok($$select public.perform_booking_operation('MANUAL',null,key,payload||'{"full_name":"Changed"}') from f$$,'23514','Operation key conflict','same key cannot change guest');
select is((select count(*)::int from public.manual_booking_contacts),1,'single private contact record');
select throws_ok($$select public.perform_booking_operation('MANUAL',null,gen_random_uuid(),payload||'{"source":"WEBSITE"}') from f$$,'23514','Invalid manual request','source spoofing rejected');
select throws_ok($$select public.perform_booking_operation('MANUAL',null,gen_random_uuid(),payload||'{"overnight_guest_count":9}') from f$$,'23514',null,'invalid occupancy rolls back');
select is((select count(*)::int from public.booking_requests),1,'no partial invalid manual request');
select lives_ok($$select public.perform_booking_operation('STATUS',request,gen_random_uuid(),'{"status":"REVIEWING","expected_status":"NEW"}') from f$$,'manager reviews request');
select throws_ok($$select public.perform_booking_operation('STATUS',request,gen_random_uuid(),'{"status":"DECLINED","expected_status":"NEW"}') from f$$,'23514','Request changed; reload','stale status rejected');
select throws_ok($$select public.perform_booking_operation('CANCEL',request,gen_random_uuid(),'{"reason":"X","refund_review_acknowledged":true}') from f$$,'42501','OWNER required','manager cannot cancel');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000091',true);
insert into public.booking_quotes(request_id,revision,amount_total,required_deposit_amount) select request,1,100,25 from f returning id;
update f set quote=(select id from public.booking_quotes where request_id=f.request);
select public.issue_booking_quote(quote) from f;
select public.perform_booking_operation('STATUS',request,gen_random_uuid(),'{"status":"AWAITING_DEPOSIT","expected_status":"QUOTED"}') from f;
update f set deposit=public.perform_booking_operation('PAYMENT',request,'00000000-0000-4000-8000-000000000095','{"amount_centavos":2500,"payment_method":"Synthetic cash","masked_reference":"***1234"}');
select is((select amount from public.booking_deposits where id=(select deposit from f)),25::numeric,'exact centavo payment recorded');
select is((select status::text from public.booking_deposits where id=(select deposit from f)),'RECORDED_UNVERIFIED','recording never verifies');
select throws_ok($$select public.perform_booking_operation('PAYMENT',request,'00000000-0000-4000-8000-000000000095','{"amount_centavos":2500,"payment_method":"Changed","masked_reference":"***1234"}') from f$$,'23514','Operation key conflict','financial key binds entire payload');
select throws_ok($$select public.confirm_booking_reservation(request,quote,gen_random_uuid()) from f$$,'23514','Required down payment has not been independently verified','cannot confirm unverified record');
select public.decide_booking_deposit(deposit,'VERIFIED',true,gen_random_uuid()) from f;
update f set reservation=public.confirm_booking_reservation(request,quote,gen_random_uuid());
select throws_ok($$select public.perform_booking_operation('COMPLETE',reservation,gen_random_uuid(),'{"reason":"Complete","refund_review_acknowledged":false}') from f$$,'23514','Stay cannot be completed before checkout','future stay completion rejected');
select throws_ok($$select public.perform_booking_operation('CANCEL',reservation,gen_random_uuid(),'{"reason":"Cancel","refund_review_acknowledged":false}') from f$$,'23514','Reason and payment review acknowledgement required','cancellation requires refund review');
reset role;
create function pg_temp.fail_cancel_audit() returns trigger language plpgsql as $$begin if new.action='CANCEL' then raise exception 'Synthetic audit failure'; end if; return new; end$$;
create trigger test_cancel_audit_failure before insert on public.booking_operation_events for each row execute function pg_temp.fail_cancel_audit();
set local role authenticated;
select throws_ok($$select public.perform_booking_operation('CANCEL',reservation,gen_random_uuid(),'{"reason":"Rollback test","refund_review_acknowledged":true}') from f$$,'P0001','Synthetic audit failure','late audit failure rolls back cancellation');
select is((select active from public.property_occupancies where reservation_id=(select reservation from f)),true,'rollback keeps original occupancy active');
select is((select count(*)::int from public.property_occupancy_events where event='RELEASED'),0,'rollback leaves no partial release event');
select is((select count(*)::int from public.booking_reservation_events where new_status='CANCELLED'),0,'rollback leaves no partial cancellation history');
reset role;
drop trigger test_cancel_audit_failure on public.booking_operation_events;
set local role authenticated;
select lives_ok($$select public.perform_booking_operation('CANCEL',reservation,'00000000-0000-4000-8000-000000000096','{"reason":"Synthetic cancellation","refund_review_acknowledged":true}') from f$$,'owner safely cancels');
select is((select active from public.property_occupancies where reservation_id=(select reservation from f)),false,'cancellation releases only linked occupancy');
select is((select status::text from public.booking_reservations where id=(select reservation from f)),'CONFIRMED','original confirmed snapshot remains immutable');
select is((public.read_booking_operations('2038-01-01','2038-02-01',(select request from f))->'reservations'->0->>'operational_status'),'CANCELLED','operational lifecycle derives cancellation event');
select is((select count(*)::int from public.booking_deposit_verifications),1,'payment decisions preserved after cancellation');
select is((select count(*)::int from public.booking_operation_events where refund_review_required),1,'refund review obligation durable');
select lives_ok($$select public.perform_booking_operation('CANCEL',reservation,'00000000-0000-4000-8000-000000000096','{"reason":"Synthetic cancellation","refund_review_acknowledged":true}') from f$$,'cancellation retry idempotent');
select throws_ok($$select public.perform_booking_operation('COMPLETE',reservation,gen_random_uuid(),'{"reason":"Complete","refund_review_acknowledged":false}') from f$$,'23514','Reservation is not active','terminal transition cannot repeat');
select throws_ok($$update public.booking_operation_events set reason='Hidden'$$,'42501',null,'direct lifecycle mutation denied');
select throws_ok($$update public.booking_reservations set status='CANCELLED'$$,'42501',null,'direct reservation mutation denied');
select throws_ok($$select public.release_booking_owner_block(reservation) from f$$,'23514','Owner block not found','cannot release reservation as owner block');
-- Complete a synthetic past stay without rewriting its occupancy or financial snapshot.
update f set key=gen_random_uuid(),payload=payload||'{"check_in_date":"2000-01-01","check_out_date":"2000-01-03"}';
update f set request=public.perform_booking_operation('MANUAL',null,key,payload);
select public.perform_booking_operation('STATUS',request,gen_random_uuid(),'{"status":"REVIEWING","expected_status":"NEW"}') from f;
insert into public.booking_quotes(request_id,revision,amount_total,required_deposit_amount) select request,1,100,25 from f;
update f set quote=(select id from public.booking_quotes where request_id=f.request);
select public.issue_booking_quote(quote) from f;
select public.perform_booking_operation('STATUS',request,gen_random_uuid(),'{"status":"AWAITING_DEPOSIT","expected_status":"QUOTED"}') from f;
update f set deposit=public.perform_booking_operation('PAYMENT',request,gen_random_uuid(),'{"amount_centavos":2500,"payment_method":"Synthetic","masked_reference":"***1234"}');
select public.decide_booking_deposit(deposit,'VERIFIED',true,gen_random_uuid()) from f;
update f set reservation=public.confirm_booking_reservation(request,quote,gen_random_uuid());
select lives_ok($$select public.perform_booking_operation('COMPLETE',reservation,gen_random_uuid(),'{"reason":"Synthetic stay completed","refund_review_acknowledged":false}') from f$$,'past stay completes with authorized lifecycle event');
select is((select active from public.property_occupancies where reservation_id=(select reservation from f)),true,'completion preserves historical occupancy');
select is((public.read_booking_operations('2000-01-01','2000-02-01',(select request from f))->'reservations'->0->>'operational_status'),'COMPLETED','operational status correctly derives completion');
select is((select count(*)::int from public.booking_quotes where status='ISSUED'),2,'all issued quote history retained');
select lives_ok($$select public.perform_booking_operation('NOTE',request,gen_random_uuid(),'{"text":"Synthetic private operational note"}') from f$$,'private operational note is append-only');
select lives_ok($$select public.perform_booking_operation('NOTIFY_RETRY',request,gen_random_uuid(),'{}') from f$$,'notification retry intent has actor audit');
reset role;
select is(public.may_deliver_booking_request_notification((select request from f)),false,'completed stay cannot send delayed pending acknowledgement');
select ok(has_function_privilege('service_role','public.may_deliver_booking_request_notification(uuid)','EXECUTE'),'notification worker has only scoped eligibility read');
select ok(not has_function_privilege('authenticated','public.may_deliver_booking_request_notification(uuid)','EXECUTE'),'admins cannot invoke worker eligibility RPC directly');
set local role anon;
select throws_ok($$select public.read_booking_operations('2038-01-01','2038-02-01',null)$$,'42501',null,'anonymous operations reads denied');
select throws_ok($$select public.perform_booking_operation('MANUAL',null,gen_random_uuid(),'{}')$$,'42501',null,'anonymous writes denied');
select throws_ok($$select * from public.manual_booking_contacts$$,'42501',null,'anonymous contacts private');
select is((select count(*)::int from public.read_booking_availability('2038-01-01','2038-01-03')),0,'public availability reflects atomic cancellation without PII');
select * from finish();
rollback;
